def wrap(text, width, indent=""):
    """Wrap `text` to lines of at most `width` characters. See TASK.md.

    Returns a list of strings (no embedded newlines).
    """
    # Rule 6: argument validation.
    if isinstance(width, bool) or not isinstance(width, int) or width < 1:
        raise ValueError("width must be an int >= 1")
    if not isinstance(indent, str):
        raise ValueError("indent must be a string")
    if len(indent) >= width:
        raise ValueError("indent must be shorter than width")

    result = []

    # Rule 1: split into paragraphs at every "\n".
    for para in text.split("\n"):
        # Rule 2: words are maximal runs of non-whitespace.
        words = para.split()

        # Rule 1: a paragraph with no words gives exactly one empty line.
        if not words:
            result.append("")
            continue

        lines = []
        is_first = True      # first line of the paragraph has no indent (Rule 4)
        current = ""         # content of the current line, without indent

        def available():
            # Space available on the current line (Rule 4 counts indent).
            return width if is_first else width - len(indent)

        def flush_current():
            nonlocal current, is_first
            if current != "":
                lines.append(current if is_first else indent + current)
                is_first = False
                current = ""

        def place_on_empty(word):
            # Place `word` on an empty current line, breaking long words (Rule 5).
            nonlocal current, is_first
            if len(word) <= available():
                current = word
            else:
                while len(word) > available():
                    cap = available()
                    piece = word[:cap]
                    lines.append(piece if is_first else indent + piece)
                    is_first = False
                    word = word[cap:]
                current = word

        for w in words:
            if current == "":
                place_on_empty(w)
            else:
                # Rule 3: greedily add the word if it fits with a separating space.
                if len(current) + 1 + len(w) <= available():
                    current = current + " " + w
                else:
                    # Does not fit: flush the current line, start a new one.
                    flush_current()
                    place_on_empty(w)

        flush_current()

        result.extend(lines)

    return result
